"""WireGuard configuration renderer."""

from pathlib import Path

from secbox.modules.vpn.models import WireGuardTunnelConfig


class VpnRenderError(ValueError):
    """Raised when VPN configuration cannot be rendered."""


def render_wireguard_config(
    tunnel: WireGuardTunnelConfig,
    output_path: Path,
) -> Path:
    lines = [
        "# Generated by SecBox",
        "",
        "[Interface]",
        f"Address = {tunnel.address}",
        f"PrivateKey = <loaded-from:{tunnel.private_key_file}>",
        "Table = off",
    ]

    if tunnel.mtu is not None:
        lines.append(f"MTU = {tunnel.mtu}")

    lines.extend(
        [
            "",
            "[Peer]",
            f"PublicKey = {tunnel.peer.public_key}",
        ]
    )

    if tunnel.peer.preshared_key_file is not None:
        lines.append(
            "PresharedKey = "
            f"<loaded-from:{tunnel.peer.preshared_key_file}>"
        )

    lines.append(
        "AllowedIPs = "
        + ", ".join(
            str(network)
            for network in tunnel.peer.allowed_ips
        )
    )

    lines.append(
        f"Endpoint = {tunnel.peer.endpoint}"
    )

    if tunnel.peer.persistent_keepalive is not None:
        lines.append(
            "PersistentKeepalive = "
            f"{tunnel.peer.persistent_keepalive}"
        )

    output_path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    output_path.write_text(
        "\n".join(lines) + "\n",
        encoding="utf-8",
    )

    return output_path
